import{_ as t,o as s,c as a,ae as o}from"./chunks/framework.Bs_1Tt6f.js";const m=JSON.parse('{"title":"Settings & Data Backup","description":"","frontmatter":{},"headers":[],"relativePath":"docs/settings-and-data.md","filePath":"docs/settings-and-data.md"}'),n={name:"docs/settings-and-data.md"};function r(i,e,l,d,h,p){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="settings-data-backup" tabindex="-1">Settings &amp; Data Backup <a class="header-anchor" href="#settings-data-backup" aria-label="Permalink to &quot;Settings &amp; Data Backup&quot;">​</a></h1><p>The <strong>Settings</strong> view holds everything about <em>where your work is kept</em>, how to back it up and move it, and the project-wide options that shape the other views.</p><h2 id="where-your-work-is-kept" tabindex="-1">Where your work is kept <a class="header-anchor" href="#where-your-work-is-kept" aria-label="Permalink to &quot;Where your work is kept&quot;">​</a></h2><p>Your annotations, equivalents tables, pattern library and settings are kept in two places:</p><ol><li><strong>Browser storage</strong> is the working copy. It is fast, but browsers may clear it (clearing site data, private windows, low disk space).</li><li><strong>A workspace folder</strong> (Settings → <strong>Project Folder</strong>, Chrome / Edge) is the permanent copy. Once a folder is chosen, every change is saved into it automatically.</li></ol><p>The status pill in the toolbar shows where things stand: <em>Saved</em>, <em>Saving…</em>, <em>No changes</em>, <em>Not saved</em> (browser storage is full) or <em>Not saving</em> (the folder&#39;s file cannot be used — nothing is written to it until you fix that).</p><h3 id="what-is-in-the-folder" tabindex="-1">What is in the folder <a class="header-anchor" href="#what-is-in-the-folder" aria-label="Permalink to &quot;What is in the folder&quot;">​</a></h3><table tabindex="0"><thead><tr><th>File</th><th>Contents</th></tr></thead><tbody><tr><td><code>workspace.json</code></td><td>settings, annotations, equivalents, pattern library, OMMR settings</td></tr><tr><td><code>direct-snippets.json</code></td><td>the image snippets of <a href="./custom-manuscripts.html">Custom Manuscripts</a> (kept separate because images are large)</td></tr></tbody></table><p>The app only ever writes these files when it can read them. A file that is damaged, or was written by a <strong>newer</strong> version of the app, is <strong>left untouched</strong> and saving is switched off with a message, so the app can never overwrite something it does not understand.</p><h3 id="safety-copies-you-may-find" tabindex="-1">Safety copies you may find <a class="header-anchor" href="#safety-copies-you-may-find" aria-label="Permalink to &quot;Safety copies you may find&quot;">​</a></h3><p>The app keeps a copy before it replaces anything. These files are never deleted by the app:</p><table tabindex="0"><thead><tr><th>File</th><th>Why it exists</th></tr></thead><tbody><tr><td><code>workspace.pre-v1.json</code></td><td>your file exactly as it was before this version upgraded it to its newer format</td></tr><tr><td><code>workspace.backup-external.json</code></td><td>the previous <code>workspace.json</code>, kept when it had been changed outside this tab (another tab, another computer) before the app replaced it</td></tr><tr><td><code>workspace.replaced-&lt;time&gt;.json</code></td><td>what the app held in the browser when the folder&#39;s own workspace was loaded instead (choosing a folder that already had one, or meeting a folder for the first time). <strong>Import</strong> it to get that work back</td></tr></tbody></table><p>Do not open the same folder in two browser tabs or two computers at once; the second one will keep the other&#39;s version as <code>workspace.backup-external.json</code>, but the two are not merged.</p><h2 id="how-the-settings-view-is-organised" tabindex="-1">How the Settings view is organised <a class="header-anchor" href="#how-the-settings-view-is-organised" aria-label="Permalink to &quot;How the Settings view is organised&quot;">​</a></h2><p>Settings shows one topic at a time; the list on the left (at the top on a phone) switches between them. The topic is part of the address (<code>#/settings?section=import</code>), so other views link straight to it.</p><table tabindex="0"><thead><tr><th>Topic</th><th>What it holds</th></tr></thead><tbody><tr><td><strong>Storage</strong></td><td>the project folder and the backup reminder</td></tr><tr><td><strong>Import</strong></td><td>loading files into the workspace</td></tr><tr><td><strong>Export</strong></td><td>backups, exports of a selection, the static public site</td></tr><tr><td><strong>Workspace contents</strong></td><td>the manuscripts that hold data, with <em>Clean up…</em> per manuscript and <em>Remove all</em></td></tr><tr><td><strong>Shared sync</strong></td><td>the monodi.app repository (see below)</td></tr><tr><td><strong>Display &amp; IDs</strong>, <strong>Signs &amp; variants</strong>, <strong>Source metadata</strong>, <strong>Folio alignment</strong></td><td>the project settings described further down</td></tr></tbody></table><h2 id="backups-and-moving-work-between-computers" tabindex="-1">Backups and moving work between computers <a class="header-anchor" href="#backups-and-moving-work-between-computers" aria-label="Permalink to &quot;Backups and moving work between computers&quot;">​</a></h2><h3 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h3><p><strong>Settings → Export</strong> is the one place to save the workspace to a file. Three presets set the check boxes; changing any box makes it a <em>Custom</em> selection.</p><ul><li><strong>Everything</strong> — a full backup: every manuscript with data, every custom manuscript, all settings. Only a full backup resets the backup reminder.</li><li><strong>Manuscripts only</strong> — all manuscript data, no settings.</li><li><strong>Settings only</strong> — no manuscript data.</li></ul><p>Below the presets, every part can be chosen on its own:</p><ul><li><strong>Manuscripts</strong> — tick single manuscripts (filter by siglum, <em>Select all</em>, <em>Published only</em>).</li><li><strong>Kinds of data</strong> — <em>Annotations</em> (line regions, snippets, manual line numbers), <em>Equivalents tables</em> (Ref IDs and notes), <em>IIIF links</em>. A file without a kind of data says so, and importing it with <em>Overwrite</em> replaces only the kinds it carries: a file with only tables never removes line regions.</li><li><strong>Custom manuscripts</strong> — tick single ones. Their images are stored inside the file.</li><li><strong>Settings</strong> — <em>Display defaults</em>, <em>Preferred IDs</em>, <em>Signs and variants</em>, <em>Source metadata</em>, <em>Folio alignments</em>, <em>Pattern library</em>, <em>OMMR import settings</em>. The backup label stays in the browser and is never exported.</li><li><strong>File</strong> — the label (part of the file name) and the format: <strong>one JSON file</strong>, or a <strong>ZIP with one file per manuscript</strong> (plus one per custom manuscript and a <code>settings.json</code>), handy for passing single manuscripts on.</li></ul><h3 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h3><p><strong>Settings → Import</strong> reads every file the app has written — backups, exports, custom-manuscript files, configuration files, workspace-folder files (also the safety copies listed above), files from older versions of the app — and ZIPs of them.</p><ol><li><strong>Drop any number of files</strong> on the import area, or click it to choose them. A ZIP is opened and each <code>.json</code> file in it is listed on its own. Files that are not <code>.json</code> or <code>.zip</code> are listed as <em>Not used</em>. More files can be added to the list before importing.</li><li><strong>Check the list.</strong> Nothing has changed yet. Each file shows its kind, label, date and contents; files that cannot be read show why. Untick a file to leave it out, or remove it with ×. Files are applied <strong>from top to bottom</strong>; older files are placed above newer ones.</li><li><strong>Choose per manuscript.</strong> A manuscript that is new is imported (or set it to <em>Skip</em>). A manuscript that is already in the workspace, or that an earlier file in the list also holds, is a <em>conflict</em> (highlighted) with these choices: <ul><li><strong>Skip (keep mine)</strong> — the default when the workspace already holds it.</li><li><strong>Merge (add, keep mine)</strong> — adds line regions, snippets and table rows from the file, updates entries with the same id, removes nothing. The default when only an earlier file in the list holds it.</li><li><strong>Overwrite mine</strong> — replaces the workspace&#39;s data of that manuscript (only the kinds of data the file carries).</li><li><strong>Import as copy</strong> — keeps both; the file&#39;s version gets the siglum &quot;… (copy)&quot;, &quot;… (copy 2)&quot;, …. <em>All conflicts</em> above the list sets every conflict at once. Custom manuscripts count as the same when they share the internal id or the siglum.</li></ul></li><li><strong>Settings.</strong> A file that carries settings has the box <em>Apply the settings in this file</em>. It is ticked for the newest such file only; settings that a file does not contain stay as they are.</li><li>Press <strong>Import</strong>. The message afterwards has <strong>Undo import</strong>, which puts the whole workspace back as it was before (until the page is left).</li></ol><p>A file written by a <em>newer</em> version of the app is refused instead of being guessed at.</p><h3 id="workspace-contents" tabindex="-1">Workspace contents <a class="header-anchor" href="#workspace-contents" aria-label="Permalink to &quot;Workspace contents&quot;">​</a></h3><p><strong>Settings → Workspace contents</strong> lists the manuscripts that hold data, with <em>Clean up…</em> to delete some or all of one manuscript&#39;s data. <strong>Remove all…</strong> wipes the annotations, line regions, equivalents tables and IIIF links of every manuscript (settings and custom manuscripts stay); it can be undone until the page is left.</p><h3 id="backup-reminder" tabindex="-1">Backup reminder <a class="header-anchor" href="#backup-reminder" aria-label="Permalink to &quot;Backup reminder&quot;">​</a></h3><p>When you have made a number of changes and have not exported for a while, a small reminder appears. Under <strong>Settings → Storage → Backup Reminder</strong> you can turn it off. With a workspace folder bound, the folder is your backup and the reminder matters less.</p><h2 id="app-defaults-and-project-settings" tabindex="-1">App Defaults and project settings <a class="header-anchor" href="#app-defaults-and-project-settings" aria-label="Permalink to &quot;App Defaults and project settings&quot;">​</a></h2><ul><li><strong>App Defaults</strong> — how patterns are drawn everywhere: <em>Graphic (SVG)</em>, <em>Arrows (↗/↘)</em> or <em>Text (u/d/e)</em>.</li><li><strong>Preferred Custom IDs</strong> — define a default Ref ID for a pattern (e.g. <code>*dd</code> → <code>Type A</code>). When you link a polygon to an occurrence of that pattern, the ID is filled in for you; you can still override it.</li><li><strong>Source Metadata</strong> — define your own attributes for manuscripts (century, region, …) and fill them in per manuscript. They become filters in the public views.</li><li><strong>Custom Signs &amp; Code Variants</strong> — define special signs (for example a virga) and the pattern variants derived from them. The switch <em>discriminate signs</em> decides whether variants are counted separately or merged into their base pattern.</li><li><strong>Manuscript Alignment</strong> — tell the app how the folios of the transcription map onto the pages of the IIIF manifest, including jumps where the manifest skips images.</li></ul><h2 id="shared-sync-monodi-app" tabindex="-1">Shared Sync (monodi.app) <a class="header-anchor" href="#shared-sync-monodi-app" aria-label="Permalink to &quot;Shared Sync (monodi.app)&quot;">​</a></h2><p>The <strong>Shared Sync</strong> panel connects the app to the GitHub repository your project shares with monodi.app (an access token with read/write <em>Contents</em> permission on that repository; it is kept only in this browser and sent only to GitHub).</p><ul><li><strong>Pull</strong> brings in source records, equivalents and annotations. It <strong>adds and updates and never removes</strong> what you have here.</li><li><strong>Push</strong> writes your equivalents, line regions and snippets back, changing only manuscripts whose data actually changed. It never removes anything in the repository and it never overwrites a newer commit.</li><li><strong>Export / Import database file</strong> exchanges the same data as one file when there is no repository.</li></ul><p>Snippets that belong to no line (shown under &quot;Unassigned&quot; in the annotation view) are not pushed.</p>',36)])])}const g=t(n,[["render",r]]);export{m as __pageData,g as default};
